-- Seed 100 réponses de test pour la session "Vos retours • 100 participants"
-- À exécuter dans l'éditeur SQL Supabase (Dashboard > SQL Editor)
--
-- Prérequis : une session avec question = 'Vos retours • 100 participants' doit exister.
-- Pour trouver votre session_id : SELECT id, question FROM workshop_sessions;

INSERT INTO public.workshop_responses (session_id, participant_name, response_text)
SELECT s.id, r.participant_name, r.response_text
FROM public.workshop_sessions s
CROSS JOIN (
  VALUES
    ('Alice', 'On ne sait jamais ce que font les autres équipes. J''ai déjà passé deux semaines sur un livrable pour découvrir qu''une autre équipe avait fait exactement la même chose en parallèle. C''est frustrant et c''est un gaspillage de ressources énorme.'),
    ('Bruno', 'Les informations se perdent entre les services, il n''y a pas de canal centralisé. On jongle entre les mails, Teams, le chat interne et les Post-it. Résultat : personne n''a la même version de l''info.'),
    ('Claire', 'Je trouve que les réunions hebdo ne suffisent pas pour avoir une vraie visibilité. On a besoin d''outils de communication asynchrone qui permettent de suivre les avancées sans multiplier les réunions.'),
    ('David', 'Les décisions sont prises sans consulter les personnes concernées. On l''apprend par un mail collectif après coup et on doit s''adapter dans l''urgence.'),
    ('Emma', 'Le manque de transparence crée de la frustration au quotidien. J''ai l''impression qu''il y a deux mondes : ceux qui savent et ceux qui subissent les décisions. Ça nuit clairement à l''engagement.'),
    ('François', 'Ce qui me pose le plus problème, c''est qu''on n''a pas de source de vérité unique. Chaque équipe a ses propres fichiers, ses propres process, et quand il faut collaborer c''est un vrai casse-tête. Il faudrait un wiki interne à jour.'),
    ('Géraldine', 'J''ai rejoint l''équipe il y a 6 mois et j''ai mis des semaines à comprendre qui fait quoi. L''organigramme n''est pas à jour, les rôles ne sont pas clairs. Un onboarding plus structuré avec une cartographie des compétences serait un vrai plus.'),
    ('Hugo', 'La communication descendante existe, mais la communication montante est quasi inexistante. Quand on remonte des problèmes terrain, on a rarement un retour. Ça donne l''impression que nos feedbacks partent dans le vide.'),
    ('Isabelle', 'Entre les sites de Paris et Lyon, la communication est catastrophique. On découvre des projets en cours par hasard. Il faudrait des points inter-sites réguliers, même courts.'),
    ('Julien', 'On perd un temps fou à chercher la bonne information. Est-ce dans le mail de lundi ? Dans le compte-rendu de réunion ? Sur le drive partagé ? Personne ne sait. Un outil de gestion de connaissances centralisé nous ferait gagner des heures chaque semaine.'),
    ('Karine', 'Le problème c''est que chaque manager a sa propre façon de communiquer. Certains envoient des mails détaillés, d''autres ne disent rien. Il faudrait un standard de communication minimum.'),
    ('Léo', 'J''apprécie les efforts récents avec la newsletter interne, mais ça ne suffit pas pour le quotidien opérationnel. On a besoin de transparence sur les décisions projet en temps réel. Et je pense que j''ai besoin de plus de formation.'),
    ('Marie', 'Les informations critiques arrivent souvent trop tard. La dernière fois, on a appris le changement de deadline 48h avant l''échéance. C''est ingérable pour organiser le travail de l''équipe.'),
    ('Nicolas', 'Quand il y a un incident en production, chaque équipe gère dans son coin. On n''a pas de canal de crise transversal. La dernière panne a duré 4h de plus que nécessaire à cause de ça.'),
    ('Ophélie', 'Ce qui manque vraiment c''est un rituel de partage inter-équipes. Pas une grande messe formelle, mais des démos courtes, informelles, pour voir ce que font les autres et créer des synergies.'),
    ('Pierre', 'La communication avec les prestataires externes est aussi un sujet. Ils n''ont pas accès aux mêmes outils que nous et l''information se perd dans des allers-retours de mails interminables.'),
    ('Quentin', 'J''aimerais avoir accès à plus de formations sur les outils qu''on utilise au quotidien. On a déployé un nouveau CRM il y a 3 mois et je n''ai eu que 30 minutes de démo. Je n''utilise probablement que 20% des fonctionnalités.'),
    ('Roxane', 'On nous demande d''utiliser de nouveaux logiciels sans formation préalable. Le résultat c''est qu''on perd du temps à bidouiller au lieu d''être efficaces. Un parcours de formation structuré pour chaque outil serait un minimum.'),
    ('Sébastien', 'La formation initiale à l''arrivée est correcte, mais ensuite il n''y a rien. Les métiers évoluent vite, et après 2-3 ans on se retrouve avec des compétences qui ne sont plus à jour. Il faudrait un plan de développement continu.'),
    ('Théo', 'Il faudrait un budget formation individuel pour se perfectionner sur les sujets qui nous intéressent. D''autres entreprises proposent 1000-1500€ par an de budget personnel, c''est un vrai levier de motivation et de fidélisation.'),
    ('Ursula', 'Les webinaires internes sont utiles mais pas assez fréquents. On en a un par trimestre alors qu''il faudrait au moins un par mois. Et il faudrait varier les sujets : soft skills, technique, management, pas juste des présentations produit.'),
    ('Vincent', 'J''aimerais beaucoup qu''on mette en place des « learning hours » hebdomadaires. Une heure dédiée où chacun peut se former, regarder un cours en ligne, lire un article technique. Chez mon ancien employeur ça marchait très bien.'),
    ('Wendy', 'Le problème c''est qu''on n''a pas le temps de se former. La charge de travail est telle qu''on repousse toujours. La formation devrait être planifiée et sanctuarisée dans l''agenda, pas optionnelle.'),
    ('Xavier', 'Les compétences data et IA deviennent incontournables dans notre métier. Mais personne n''a été formé. On regarde les autres entreprises se transformer pendant qu''on reste sur nos acquis.'),
    ('Yasmine', 'Je souhaiterais des formations certifiantes qui puissent être valorisées. Pas juste des présentations internes, mais de vrais parcours reconnus qui motivent les collaborateurs à investir du temps.'),
    ('Zoé', 'L''apprentissage entre pairs est sous-exploité chez nous. On a des experts dans plein de domaines mais on ne partage pas assez. Des sessions de type « lunch & learn » ou « brown bag sessions » seraient géniales.'),
    ('Antoine', 'Pour les managers, il n''y a quasiment aucune formation au management. On promeut des experts techniques à des postes de managers sans les accompagner. Résultat : ils sont malheureux et leurs équipes aussi.'),
    ('Béatrice', 'J''ai demandé une formation il y a 8 mois. Elle a été validée par mon manager puis refusée par les RH pour raison budgétaire. Le processus est trop opaque et décourageant.'),
    ('Cédric', 'Il faudrait une plateforme e-learning accessible à tous, avec du contenu de qualité. Type LinkedIn Learning ou Coursera. C''est un investissement mais le ROI en compétences est immense.'),
    ('Delphine', 'Les nouvelles méthodes de travail (Design Thinking, Lean, OKR) ne sont connues que par quelques personnes. Si on veut vraiment les adopter, il faut former massivement, pas juste envoyer un PDF.'),
    ('Éric', 'Notre CRM est lent et ne correspond plus à nos besoins actuels. Il plante régulièrement, l''interface date des années 2010, et il nous manque des fonctionnalités basiques comme le suivi des interactions multicanal. Il est temps de migrer.'),
    ('Fatima', 'Il faudrait moderniser notre intranet, personne ne l''utilise. La dernière mise à jour date de 2019. Quand je cherche un document, c''est plus rapide de demander à un collègue que de naviguer dans l''arborescence.'),
    ('Guillaume', 'Pourquoi ne pas adopter des outils collaboratifs modernes comme Notion, Slack ou Figma ? On utilise encore des fichiers Word partagés par mail pour collaborer. En 2026, c''est aberrant.'),
    ('Hélène', 'Les outils de reporting sont trop complexes pour un usage quotidien. Chaque rapport nécessite 3h de manipulation Excel. Un outil de BI en self-service avec des dashboards pré-configurés changerait tout.'),
    ('Ivan', 'On devrait automatiser les tâches répétitives avec des workflows. Je passe 2h par jour sur des tâches administratives qui pourraient être automatisées : relances, saisie de données, génération de rapports standards.'),
    ('Jade', 'L''accès VPN est instable, ce qui rend le télétravail pénible. Je perds la connexion au moins 3 fois par jour. Il existe des solutions zero-trust plus modernes et plus fiables.'),
    ('Kevin', 'On a trop d''outils qui font la même chose. Entre l''outil officiel et les solutions adoptées par chaque équipe, on a 4 outils de gestion de tâches différents. Il faudrait rationaliser et choisir un seul outil pour chaque usage.'),
    ('Laure', 'Notre outil de ticketing est une catastrophe UX. Les développeurs passent plus de temps à remplir les tickets qu''à coder. On devrait migrer vers Jira ou Linear, quelque chose de moderne et rapide.'),
    ('Maxime', 'L''app mobile interne n''est pas responsive et certaines fonctionnalités ne marchent tout simplement pas sur téléphone. Quand on est en déplacement, c''est très handicapant.'),
    ('Nadia', 'Le stockage de fichiers est éclaté entre le NAS, SharePoint, Google Drive et des clés USB. On ne retrouve plus rien. Une politique claire de stockage avec un seul outil serait salvatrice.'),
    ('Olivier', 'Les performances de notre ERP sont inacceptables. Charger une facture prend 15 secondes. Multiplié par 200 factures par jour, ça fait presque une heure perdue.'),
    ('Pauline', 'On n''a pas d''outil de signature électronique officiel. On imprime, on signe, on scanne, on envoie par mail. C''est archaïque et ça ralentit tous les processus contractuels.'),
    ('Raphaël', 'Où va-t-on exactement ? La vision à 3 ans n''est pas claire. On entend parler de transformation digitale, d''internationalisation, d''innovation, mais concrètement quelles sont les priorités ? J''aimerais comprendre comment mon travail s''inscrit dans cette vision.'),
    ('Sophie', 'Comment notre travail au quotidien s''inscrit dans la stratégie globale ? On fait des projets, on livre, mais on ne sait pas si c''est aligné avec les objectifs de l''entreprise. Un lien plus explicite entre stratégie et opérations serait motivant.'),
    ('Thomas', 'Les priorités changent trop souvent, c''est déstabilisant. En 6 mois, on a eu 3 réorganisations et 2 changements de cap. Les équipes ont besoin de stabilité pour être performantes.'),
    ('Valérie', 'J''aimerais comprendre pourquoi certains projets sont abandonnés du jour au lendemain alors qu''on y a investi des mois de travail. Un minimum d''explication serait respectueux envers les équipes qui se sont investies.'),
    ('William', 'La stratégie devrait être co-construite avec les collaborateurs. On a une expertise terrain que la direction n''a pas. Des ateliers de co-construction stratégique créeraient de l''adhésion et de meilleures décisions.'),
    ('Yannick', 'On parle beaucoup d''innovation mais on ne nous donne pas les moyens d''innover. Pas de budget R&D, pas de temps dédié, pas de droit à l''erreur. L''innovation ne se décrète pas, elle se cultive.'),
    ('Aurélie', 'Le décalage entre le discours managérial (agilité, autonomie, confiance) et la réalité (process lourds, validations multiples, contrôle) est flagrant. Il faudrait aligner les actes avec les paroles.'),
    ('Baptiste', 'Je me demande quelle est notre position face à la concurrence. On ne nous partage jamais d''analyse concurrentielle. Comprendre notre positionnement nous aiderait à mieux défendre notre offre.'),
    ('Camille', 'L''absence de communication sur les résultats financiers crée de l''inquiétude. On entend des rumeurs de restructuration sans avoir aucun élément factuel. La transparence réduirait l''anxiété collective.'),
    ('Damien', 'Notre marché évolue très vite avec l''arrivée de nouveaux acteurs tech. Quelle est notre réponse ? J''ai l''impression qu''on attend de voir plutôt que d''anticiper.'),
    ('Élise', 'L''ambiance dans l''équipe est vraiment top, c''est ce qui me fait rester. Même dans les périodes de rush, on garde le sourire et on s''entraide. C''est rare et précieux.'),
    ('Fabien', 'Je me sens bien au travail grâce à mes collègues bienveillants. Il y a un vrai respect mutuel et une écoute sincère. Quand j''ai traversé une période difficile personnellement, tout le monde a été là.'),
    ('Gaëlle', 'L''entraide est naturelle ici, c''est appréciable. Quand quelqu''un est en difficulté sur un sujet, il y a toujours un collègue pour proposer son aide sans qu''on ait besoin de demander.'),
    ('Hervé', 'Les événements d''équipe (afterworks, team buildings, petits-déjeuners) renforcent notre cohésion. Ce n''est pas juste du « fun corporate », ça crée de vrais liens humains qui facilitent ensuite le travail au quotidien.'),
    ('Inès', 'C''est une vraie force de pouvoir compter les uns sur les autres. Dans mon équipe, personne ne laisse tomber un collègue. Ce sentiment de sécurité psychologique est la base de notre performance.'),
    ('Joël', 'L''intégration des nouveaux est exemplaire. Quand je suis arrivé, tout le monde a pris le temps de m''accueillir, de m''expliquer, de m''inclure dans les rituels. Je me suis senti chez moi dès la première semaine.'),
    ('Katia', 'La diversité de profils dans l''équipe est une richesse. On a des parcours très différents et c''est ça qui rend nos discussions riches et nos solutions créatives.'),
    ('Lucas', 'Mon manager fait un excellent travail pour maintenir l''ambiance. Il est à l''écoute, il désamorce les tensions rapidement, et il sait célébrer les petites victoires. Un bon manager ça change tout.'),
    ('Margaux', 'Même en télétravail, l''esprit d''équipe reste fort. On a gardé nos rituels (café virtuel du matin, rétrospectives fun) et ça maintient le lien humain malgré la distance.'),
    ('Nathan', 'On n''arrive pas à recruter assez vite, les postes restent vacants 4 à 6 mois en moyenne. Pendant ce temps, l''équipe absorbe la charge, ce qui crée de l''épuisement et de la démotivation. C''est un cercle vicieux : plus on est épuisés, moins l''équipe est attractive.'),
    ('Océane', 'La surcharge de travail due au sous-effectif impacte la qualité de ce qu''on livre. On fait du mieux qu''on peut mais on rogne sur les tests, la documentation, le polissage. À terme ça crée de la dette technique et des problèmes clients.'),
    ('Patrick', 'Il faudrait revoir notre marque employeur pour attirer plus de candidats. Notre site carrières est austère, nos offres d''emploi sont des copier-coller génériques. Les talents vont là où l''entreprise fait envie.'),
    ('Rémi', 'Les processus de validation RH sont trop lents. Entre l''identification du besoin et la publication de l''offre, il se passe 6 semaines. Dans le marché actuel, les bons profils ne restent pas disponibles aussi longtemps.'),
    ('Sarah', 'On perd des bons candidats à cause de nos délais de réponse. La dernière fois, un excellent profil a signé ailleurs pendant qu''on attendait le retour du comité de validation. Il faut raccourcir le process à 2 semaines max.'),
    ('Tristan', 'Le programme de cooptation n''est pas assez incitatif. La prime est trop faible et versée trop tard. Si on la doublait et qu''on la versait à la fin de la période d''essai, on aurait beaucoup plus de recommandations.'),
    ('Ugo', 'On devrait être présents dans les écoles et les meetups tech. Notre visibilité dans l''écosystème est quasi nulle. Les étudiants et jeunes diplômés ne nous connaissent pas.'),
    ('Virginie', 'Les fiches de poste sont trop exigeantes et découragent des candidats qui pourraient monter en compétences. « 5 ans d''expérience minimum en React, TypeScript, AWS et GraphQL »… sérieusement ? On cherche des licornes au lieu de former des potentiels.'),
    ('Wanda', 'Un système de parrainage pour les nouveaux arrivants serait très utile. Les premiers mois sont déterminants et avoir un référent qui n''est pas le manager direct permettrait de poser des questions « bêtes » sans pression.'),
    ('Yves', 'Les seniors ont énormément de connaissances à transmettre mais ça se perd. Des sessions de mentorat régulières, même 1h par mois, permettraient de capitaliser sur cette expertise avant les départs en retraite.'),
    ('Zara', 'Le mentorat pourrait aussi aider à la mobilité interne. Aujourd''hui on ne connaît pas les métiers des autres services. Un mentor d''un autre département ouvrirait des perspectives de carrière.'),
    ('Adrien', 'J''aurais aimé avoir un mentor quand je suis arrivé dans l''entreprise. J''ai mis 6 mois à comprendre les codes, la culture, les réseaux informels. Avec un parrain, ça aurait pris 6 semaines.'),
    ('Brigitte', 'Ça créerait du lien intergénérationnel dans l''entreprise. Les juniors apporteraient leur regard neuf et leur maîtrise du digital, les seniors leur expérience et leur réseau. Gagnant-gagnant.'),
    ('Charles', 'J''ai vu ça fonctionner dans mon ancienne boîte. Le programme de mentorat était structuré : matching basé sur les objectifs, points mensuels, évaluation semestrielle. Ça avait un vrai impact sur la rétention des talents.'),
    ('Diane', 'Le mentorat inversé serait intéressant aussi. Les juniors pourraient former les seniors aux nouveaux outils digitaux. Ça valorise les jeunes et ça décloisonne les générations.'),
    ('Étienne', 'On fait des efforts considérables mais on n''a jamais de retour positif. La seule fois où on entend parler de nous, c''est quand il y a un problème. Un feedback positif de temps en temps ferait tellement de bien.'),
    ('Flore', 'La reconnaissance ne passe pas que par le salaire, un simple merci sincère compte énormément. Un mail de félicitations de la direction après un projet réussi, une mention en réunion d''équipe... Ces petits gestes ont un impact immense sur le moral.'),
    ('Gaspard', 'Il faudrait célébrer davantage les succès d''équipe. On enchaîne les projets sans jamais marquer le coup. Un pot, un mail de remerciement, une rétrospective positive... quelque chose pour reconnaître le travail accompli.'),
    ('Hannah', 'Les évaluations annuelles ne reflètent pas le travail réel fourni pendant l''année. En 30 minutes, on ne peut pas couvrir 12 mois d''efforts. Des points trimestriels seraient plus justes et plus utiles.'),
    ('Irène', 'Un système de reconnaissance entre pairs serait motivant. Pouvoir dire publiquement « merci à Claire pour son aide sur le projet X » valorise et crée une culture positive.'),
    ('Jacques', 'J''ai porté un projet stratégique pendant 8 mois, livré dans les temps et sous le budget. Pas un mot de remerciement. Mon collègue dans une autre boîte a eu un bonus et une promotion pour moins que ça. Ça fait réfléchir.'),
    ('Lena', 'Le télétravail devrait être étendu à 3 jours par semaine minimum. Les jours où je suis au bureau, je passe 2h dans les transports et je suis constamment interrompu. Mes jours de télétravail sont mes jours les plus productifs.'),
    ('Marius', 'Les horaires rigides (9h-18h obligatoire) ne correspondent plus aux modes de vie actuels. Certains sont plus efficaces tôt le matin, d''autres tard le soir. La flexibilité c''est faire confiance aux adultes pour organiser leur temps.'),
    ('Noémie', 'La flexibilité permettrait de mieux gérer les contraintes familiales sans culpabiliser. Pouvoir emmener ses enfants à l''école et commencer à 9h30, c''est pas la mer à boire. Le résultat compte plus que les heures de présence.'),
    ('Oscar', 'On est plus productif quand on peut organiser son temps librement, c''est prouvé par toutes les études. Le présentéisme est un fléau français. Jugeons les résultats, pas les heures de chaise.'),
    ('Priscilla', 'D''autres entreprises du secteur offrent beaucoup plus de souplesse et ça joue directement sur l''attractivité. J''ai deux collègues qui sont partis cette année pour des boîtes full remote. Si on ne s''adapte pas, on va continuer à perdre des talents.'),
    ('Roland', 'On devrait réduire drastiquement les déplacements professionnels en avion. La moitié des voyages pourraient être remplacés par des visioconférences. C''est bon pour la planète ET pour le budget.'),
    ('Sylvie', 'Pourquoi ne pas passer au zéro papier dans tous les services ? On imprime encore des tonnes de documents qui finissent à la poubelle. Avec la signature électronique et les outils digitaux, c''est parfaitement faisable.'),
    ('Thibaut', 'L''entreprise devrait publier son bilan carbone annuel et se fixer des objectifs de réduction ambitieux. Les jeunes générations en particulier sont sensibles à cet engagement. C''est aussi un argument commercial face aux clients qui ont des critères RSE.'),
    ('Ursule', 'Les fournisseurs devraient être sélectionnés aussi sur des critères écologiques et pas uniquement sur le prix. On ne peut pas prôner la responsabilité environnementale et acheter au moins-disant sans regarder l''impact.'),
    ('Véronique', 'Notre expertise technique est reconnue par nos clients, c''est une vraie fierté. Lors du dernier audit, le client a souligné la qualité exceptionnelle de notre code et de notre architecture. C''est le fruit d''années d''investissement dans les compétences.'),
    ('Wilfried', 'On a des profils très pointus qui font la différence sur les appels d''offres. Notre capacité à résoudre des problèmes complexes est ce qui nous distingue de la concurrence. Il faut continuer à investir dans ces expertises.'),
    ('Ximena', 'La qualité de nos livrables est un vrai atout concurrentiel. Les clients savent que quand c''est nous, c''est solide, bien pensé et maintenable. Cette réputation se construit projet après projet.'),
    ('Yolande', 'La charge de travail est devenue insoutenable depuis 6 mois. Je travaille régulièrement le soir et le week-end pour tenir les délais. Mon médecin m''a dit que je montrais des signes d''épuisement professionnel. Il faut que ça change.'),
    ('Zacharie', 'Je vois des collègues au bord de l''épuisement et personne ne réagit. Les arrêts maladie se multiplient dans l''équipe. Quand quelqu''un s''arrête, sa charge est répartie sur les autres et ça aggrave le problème. C''est un engrenage dangereux.'),
    ('Arnaud', 'Les deadlines irréalistes génèrent un stress permanent qui mine le moral de toute l''équipe. On nous demande de livrer en 2 semaines ce qui en nécessite 6. Puis on nous reproche la qualité insuffisante. C''est absurde.'),
    ('Blanche', 'On manque cruellement d''espaces pour brainstormer en petit groupe. Les seules options sont la grande salle de réunion (toujours réservée) ou le couloir. Des petits espaces modulables avec des tableaux blancs seraient parfaits.'),
    ('Clément', 'Les salles de réunion sont systématiquement occupées. J''ai essayé de réserver un créneau la semaine prochaine : tout est pris. Il en faut plus, ou il faut mieux gérer les réservations fantômes.'),
    ('Dorothée', 'Comment l''IA va-t-elle impacter nos métiers concrètement ? J''entends des discours contradictoires : certains disent que ça va tout révolutionner, d''autres que c''est du hype. J''aimerais une vision claire de la direction sur ce sujet.')
) AS r(participant_name, response_text)
WHERE s.question = 'Vos retours • 100 participants';

-- Si aucune ligne n'est insérée : vérifiez le titre exact avec
--   SELECT id, question FROM workshop_sessions;
-- puis remplacez la chaîne dans le WHERE par votre question exacte.
